function drawCustom30(ui,key,label){const canvas=ui.q('statsCanvas');if(!canvas)return;const wrap=canvas.parentElement,W=Math.max(300,Math.min(920,wrap?.clientWidth||760)),H=350,dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);const rows=customRows30(ui,key),pad={l:58,r:18,t:24,b:38};ctx.font='12px system-ui';ctx.fillStyle='#93a6bf';if(!rows.length){ctx.fillText('이 조건에서 표시할 V0.30 연간 기록이 없습니다.',24,45);return;}let min=Math.min(...rows.map(x=>x.value)),max=Math.max(...rows.map(x=>x.value));if(min===max){min=Math.max(0,min-1);max+=1;}const margin=(max-min)*.08||1;min=Math.max(0,min-margin);max+=margin;const x0=pad.l,cw=W-pad.l-pad.r,ch=H-pad.t-pad.b,xf=y=>rows.length===1?x0+cw/2:x0+(y-rows[0].year)/(rows.at(-1).year-rows[0].year||1)*cw,yf=x=>pad.t+(max-x)/(max-min)*ch;ctx.strokeStyle='#2a3d58';for(let i=0;i<=4;i++){const y=pad.t+ch*i/4,val=max-(max-min)*i/4;ctx.beginPath();ctx.moveTo(x0,y);ctx.lineTo(x0+cw,y);ctx.stroke();ctx.fillStyle='#93a6bf';ctx.textAlign='right';ctx.fillText(Math.abs(val)>=1000?Math.round(val).toLocaleString():val.toFixed(Math.abs(max-min)<10?2:1),x0-7,y+4);}ctx.strokeStyle='#69adff';ctx.lineWidth=2.5;ctx.beginPath();rows.forEach((r,i)=>{const x=xf(r.year),y=yf(r.value);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();ctx.fillStyle='#eef5ff';ctx.textAlign='left';ctx.font='700 13px system-ui';ctx.fillText(label,pad.l,pad.t-7);ctx.font='11px system-ui';ctx.fillStyle='#93a6bf';ctx.textAlign='center';for(const i of [0,Math.floor((rows.length-1)/2),rows.length-1].filter((v,i,a)=>a.indexOf(v)===i))ctx.fillText(`${rows[i].year}년`,xf(rows[i].year),H-14);const last=rows.at(-1);ctx.fillStyle='#eef5ff';ctx.textAlign='right';ctx.fillText(`최근 ${last.year}년 · ${last.value.toLocaleString(undefined,{maximumFractionDigits:3})}`,W-pad.r,pad.t-7);}

